'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { 
  Home, 
  BookOpen, 
  Calendar, 
  FileText, 
  Award, 
  Bot, 
  Search, 
  Bell, 
  CheckCircle2, 
  Clock, 
  Play, 
  Sparkles,
  ArrowLeft,
  ShieldCheck,
  Fingerprint
} from 'lucide-react';
import { getLessonsByStudent, getSubjectsByStudent } from '../../data/microcurriculum';

export default function AvrilDashboard() {
  const [lessons, setLessons] = useState(() => getLessonsByStudent('avril'));
  const [subjectsInfo] = useState(() => getSubjectsByStudent('avril'));

  const toggleComplete = (id: string) => {
    setLessons((prev) =>
      prev.map((l) => (l.id === id ? { ...l, completed: !l.completed } : l))
    );
  };

  const validateProgress = () => {
    setLessons((prev) =>
      prev.map((l) => (l.completed ? { ...l, parentApproved: true } : l))
    );
  };

  const approvedCount = lessons.filter((l) => l.parentApproved).length;
  const currentProgress = lessons.length > 0 ? Math.round((approvedCount / lessons.length) * 100) : 0;
  const pendingApproval = lessons.some((l) => l.completed && !l.parentApproved);
  const hasCompletedLessons = lessons.some((l) => l.completed);

  const teachers = subjectsInfo.map(sub => ({
    name: sub.tutor.name,
    avatarColor: sub.tutor.avatarColor,
    subject: sub.name
  }));

  return (
    <div className="min-h-screen bg-[#F0F5FA] p-3 sm:p-6 flex items-center justify-center font-sans">
      
      {/* Contenedor Principal Estilo Tablet */}
      <div className="w-full max-w-[1400px] bg-white rounded-[32px] sm:rounded-[40px] shadow-2xl border border-slate-200/80 overflow-hidden flex flex-col md:flex-row min-h-[90vh]">
        
        {/* Barra Lateral Curva */}
        <aside className="w-full md:w-28 bg-gradient-to-b from-sky-400 via-blue-500 to-indigo-600 p-4 md:py-8 flex md:flex-col items-center justify-between gap-6 text-white md:rounded-r-[36px] shadow-lg">
          
          {/* Logo enmarcado armónicamente */}
          <Link 
            href="/" 
            className="w-18 h-18 sm:w-20 sm:h-20 bg-white rounded-3xl flex items-center justify-center p-2.5 overflow-hidden shadow-md hover:scale-105 transition-transform" 
            title="Wisdom School"
          >
            <Image 
              src="/logo.png" 
              alt="Logo" 
              width={70} 
              height={70} 
              className="object-contain scale-[1.7]" 
              priority 
            />
          </Link>

          <nav className="flex md:flex-col items-center gap-4 sm:gap-6">
            <button className="w-12 h-12 rounded-2xl bg-white/20 backdrop-blur-md flex items-center justify-center hover:bg-white hover:text-blue-600 transition-all">
              <Home className="w-6 h-6" />
            </button>
            <button className="w-12 h-12 rounded-2xl bg-white/10 hover:bg-white/20 flex items-center justify-center transition-all">
              <BookOpen className="w-6 h-6" />
            </button>
            <button className="w-12 h-12 rounded-2xl bg-white/10 hover:bg-white/20 flex items-center justify-center transition-all">
              <Calendar className="w-6 h-6" />
            </button>
            <button className="w-12 h-12 rounded-2xl bg-white/10 hover:bg-white/20 flex items-center justify-center transition-all">
              <FileText className="w-6 h-6" />
            </button>
            <button className="w-12 h-12 rounded-2xl bg-white/10 hover:bg-white/20 flex items-center justify-center transition-all">
              <Bot className="w-6 h-6" />
            </button>
          </nav>

          <Link href="/" className="w-11 h-11 rounded-2xl bg-white/15 hover:bg-rose-500/80 flex items-center justify-center transition-all" title="Volver al inicio">
            <ArrowLeft className="w-5 h-5" />
          </Link>
        </aside>

        {/* Panel Central */}
        <main className="flex-1 p-4 sm:p-6 md:p-8 lg:p-10 flex flex-col justify-between gap-6 bg-[#FAFBFD]">
          
          {/* Barra Superior */}
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div>
              <h1 className="text-2xl sm:text-3xl md:text-4xl font-black text-slate-900 tracking-tight">
                ¡Hola Avril! 👋
              </h1>
              <p className="text-sm sm:text-base font-semibold text-slate-400">
                Bienvenida a tu jornada escolar • 8vo de Básica (Secundaria Básica)
              </p>
            </div>

            <div className="flex items-center gap-3">
              <div className="flex items-center bg-white px-4 py-2.5 rounded-2xl border border-slate-200/80 shadow-sm text-xs sm:text-sm font-semibold text-slate-500 gap-2">
                <Search className="w-4 h-4 text-slate-400" />
                <input type="text" placeholder="Buscar lección..." className="bg-transparent outline-none w-28 sm:w-36 md:w-44" />
              </div>
              <button className="w-10 h-10 sm:w-11 sm:h-11 rounded-2xl bg-white border border-slate-200/80 flex items-center justify-center text-slate-600 hover:bg-slate-50 shadow-sm">
                <Bell className="w-4 h-4 sm:w-5 sm:h-5" />
              </button>
            </div>
          </div>

          {/* Tarjetas Superiores */}
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            
            {/* Objetivo del Día */}
            <div className="lg:col-span-6 rounded-3xl p-6 sm:p-8 md:p-10 text-white shadow-lg relative overflow-hidden flex flex-col justify-between min-h-[180px] md:min-h-[200px] bg-gradient-to-r from-indigo-600 via-blue-600 to-sky-500">
              <div className="relative z-10 flex justify-between items-start">
                <div>
                  <span className="text-xs sm:text-sm font-bold uppercase tracking-wider bg-white/20 px-3 py-1 rounded-full">
                    Objetivo de Hoy
                  </span>
                  <h3 className="text-xl sm:text-2xl md:text-3xl font-extrabold mt-3 leading-snug">
                    Comprender los ciclos de la materia y resolver el reto socrático
                  </h3>
                </div>
              </div>
              <div className="relative z-10 flex items-center gap-2 text-xs sm:text-sm font-semibold pt-4">
                <Sparkles className="w-4 h-4 text-amber-300" />
                <span>3 Clases programadas para hoy</span>
              </div>
            </div>

            {/* Medidor de Progreso */}
            <div className="lg:col-span-4 bg-white rounded-3xl p-6 border border-slate-200/80 shadow-sm flex flex-col items-center justify-center text-center">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-400 mb-2">
                Progreso Aprobado por Padres
              </span>
              <div className="relative w-24 h-24 flex items-center justify-center">
                <svg className="w-full h-full transform -rotate-90" viewBox="0 0 36 36">
                  <path
                    className="text-slate-100"
                    strokeWidth="3.5"
                    stroke="currentColor"
                    fill="none"
                    d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
                  />
                  <path
                    className="text-emerald-500 transition-all duration-500"
                    strokeDasharray={`${currentProgress}, 100`}
                    strokeWidth="3.5"
                    strokeLinecap="round"
                    stroke="currentColor"
                    fill="none"
                    d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
                  />
                </svg>
                <span className="absolute text-xl font-black text-slate-800">
                  {currentProgress}%
                </span>
              </div>
              <span className="text-[11px] font-bold text-slate-500 mt-2">
                {approvedCount} de {lessons.length} validadas
              </span>
              {pendingApproval && (
                <div className="mt-3 p-2.5 rounded-xl bg-amber-50 border border-amber-200 text-xs font-semibold text-amber-800 flex items-center gap-1.5">
                  <Fingerprint className="w-4 h-4" /> Pendiente de validación
                </div>
              )}
              {!pendingApproval && currentProgress > 0 && (
                <div className="mt-3 p-2.5 rounded-xl bg-emerald-50 border border-emerald-200 text-xs font-semibold text-emerald-800 flex items-center gap-1.5">
                  <ShieldCheck className="w-4 h-4" /> Aprobado por padres
                </div>
              )}
            </div>

            {/* Validador de Padres */}
            <div className="lg:col-span-3 bg-white rounded-3xl p-6 border border-slate-200/80 shadow-sm flex flex-col items-center justify-center text-center">
              <span className="text-xs font-bold uppercase tracking-wider text-slate-400 mb-3">
                Validador Parental
              </span>
              <button
                onClick={validateProgress}
                disabled={!hasCompletedLessons}
                className={`px-5 py-3 rounded-2xl font-black text-xs transition-all flex items-center justify-center gap-2 ${
                  hasCompletedLessons
                    ? 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-lg shadow-emerald-200'
                    : 'bg-slate-200 text-slate-400 cursor-not-allowed'
                }`}
              >
                <ShieldCheck className="w-5 h-5" />
                Aprobar Avance
              </button>
              <p className="text-[10px] text-slate-400 mt-3 leading-relaxed">
                Los padres validan el avance al hacer clic
              </p>
            </div>

            {/* Racha */}
            <div className="lg:col-span-3 bg-white rounded-3xl p-6 border border-slate-200/80 shadow-sm flex flex-col justify-between">
              <div>
                <span className="text-xs font-bold uppercase tracking-wider text-slate-400">
                  Racha Activa
                </span>
                <div className="flex items-center gap-2 mt-2">
                  <Award className="w-7 h-7 text-amber-500" />
                  <span className="text-3xl font-black text-slate-800">5 Días</span>
                </div>
              </div>
              <p className="text-xs text-slate-500 leading-relaxed">
                ¡Gran constancia! Mantén tu ritmo para ganar la insignia semanal.
              </p>
            </div>
          </div>
          <div>
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-extrabold text-slate-900">
                Clases del Día
              </h3>
              <span className="text-xs font-bold text-sky-600 bg-sky-50 px-3 py-1 rounded-full">
                Microcurrículo Activo
              </span>
            </div>

            <div className="space-y-4 sm:space-y-5">
              {lessons.map((lesson) => {
                const sub = subjectsInfo.find((s) => s.id === lesson.subjectId);
                return (
                  <div 
                    key={lesson.id} 
                    className={`p-4 sm:p-6 md:p-8 rounded-2xl bg-white border transition-all flex flex-col sm:flex-row sm:items-center justify-between gap-4 shadow-sm ${
                      lesson.parentApproved ? 'border-emerald-200 bg-emerald-50/20' : 'border-slate-200/80 hover:border-slate-300'
                    }`}
                  >
                    <div className="flex items-center gap-4">
                      <div className={`w-12 h-12 sm:w-14 sm:h-14 rounded-xl flex items-center justify-center font-bold text-white shadow-sm ${lesson.subjectColor}`}>
                        <BookOpen className="w-5 h-5 sm:w-6 sm:h-6" />
                      </div>
                      <div>
                        <div className="flex items-center gap-2">
                          <h4 className="font-extrabold text-slate-900 text-base sm:text-lg">{lesson.subjectName}</h4>
                          <span className="text-[11px] sm:text-xs font-semibold text-slate-400 flex items-center gap-1">
                            <Clock className="w-3 h-3" /> {lesson.time}
                          </span>
                        </div>
                        <p className="text-xs sm:text-sm text-slate-600 font-medium mt-0.5">
                          {lesson.description} • <span className="text-slate-400">Prof. {lesson.tutorName}</span>
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-3 self-end sm:self-center">
                      <button 
                        onClick={() => toggleComplete(lesson.id)}
                        className={`px-5 py-3 rounded-xl text-xs sm:text-sm font-bold transition-all flex items-center gap-1.5 ${
                          lesson.parentApproved 
                            ? 'bg-emerald-500 text-white shadow-sm' 
                            : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                        }`}
                      >
                        <CheckCircle2 className="w-4 h-4" />
                        {lesson.parentApproved ? 'Validado' : 'Marcar lista'}
                      </button>
                      <button className="px-5 py-3 rounded-xl text-xs sm:text-sm font-bold bg-sky-600 text-white hover:bg-sky-700 transition-all flex items-center gap-1.5 shadow-sm">
                        <Play className="w-3.5 h-3.5 fill-current" />
                        Entrar
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Profesores Virtuales */}
          <div className="bg-white rounded-3xl p-6 border border-slate-200/80 shadow-sm">
            <h3 className="text-sm font-extrabold uppercase tracking-wider text-slate-400 mb-4">
              Tus Profesores Virtuales Especialistas
            </h3>
            <div className="flex flex-wrap items-center gap-6">
              {teachers.map((t, idx) => (
                <div key={idx} className="flex flex-col items-center gap-2 group cursor-pointer">
                  <div className={`w-14 h-14 rounded-full flex items-center justify-center font-bold text-white shadow-md text-base transition-transform group-hover:scale-110 ${t.avatarColor}`}>
                    {t.name.charAt(0)}
                  </div>
                  <div className="text-center">
                    <span className="text-xs font-bold text-slate-800 block leading-tight">{t.name}</span>
                    <span className="text-[10px] font-semibold text-slate-400">{t.subject}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

        </main>

      </div>

    </div>
  );
}